import{errorMessage as message,noticeCode,NOTICES}from './messages.js?ver=c8a24342f7';export const EXACT={load_must_be_positive:'Enter a load greater than 0 watts.',loads_required:'Add at least one appliance.',bank_voltage_not_multiple_of_battery:'The bank voltage must be a whole multiple of the battery voltage (for example 24 V = 2 × 12 V).',cable_far_too_small_for_load:'This cable is far too thin for this load and length. Use a thicker cable and confirm with a licensed electrician.',city_unknown:'We do not have sun data for this city yet. Pick the nearest city or enter the yield yourself.',inverter_ac_must_use_less:'The inverter AC must use less power than the non-inverter AC for a payback to exist.',inverter_ac_no_payback:'At these figures the saving is too small to pay back the extra price within the working life of an air conditioner. Check the hours a year, the tariff and both power figures.',n_parallel_must_be_whole:'Number of parallel strings must be a whole number.',n_series_must_be_whole:'Number of batteries in series must be a whole number.',range_invalid:'The low end of the price range must be below the high end.',solar_covers_load:'Your solar covers the whole daily load even on a cloudy day, so the battery does not run down.',tariff_data_missing:'Tariff data could not be loaded. Please refresh the page.',tou_required_at_5kw:'Connections of 5 kW or more use a Time-of-Use meter: see the ToU bill link under Sanctioned load.',type_invalid:'Choose MPPT or PWM.',usage_required:'Enter your monthly units or daily kWh.',yield_or_city_or_psh_required:'Pick a city or enter peak sun hours.',ac_protected_lost:'With the AC your monthly total goes over the protected limit, so this bill and the bills of the following six months are charged at unprotected rates. Fewer AC hours may keep you protected.',ac_above_sanctioned:'This AC alone is above your sanctioned load: apply for a higher one before installing it.',monthly_units_all_zero:'Enter the units of at least one month.',length_invalid:'enter a cable length in metres.',period_unknown:'We do not have the QTA rate for that quarter. Enter the QTA from your bill.',surge_w_required:'Enter the starting (surge) watts of your load, or leave both surge fields blank.',surge_rating_w_required:'Enter the UPS surge rating from its label, or leave both surge fields blank.',appliance_unknown:'Pick an appliance from the list, or choose Custom and enter its watts.',load_exceeds_ups_rating:'This load is more than the UPS can deliver (VA × power factor). Choose a bigger UPS or reduce the load.',surge_exceeds_ups_rating:'The starting surge is above the UPS surge rating. Choose a bigger UPS or remove the motor load.',other_start_below_run:'Starting watts of the other loads cannot be lower than their running watts.',loads_hours_required:'Enter hours per day for at least one appliance.',cable_data_missing:'Cable data could not be loaded. Please refresh the page.',cable_size_unknown:'Pick a standard cable size.',load_above_standard_breakers:'This load needs more than the largest single-phase MCB. Split it into separate circuits or ask a licensed electrician about a three-phase connection.',dc_load_above_cable_table:'This battery current is above the largest cable in our table. Do not split a battery feed into separate circuits: use a higher battery voltage (it lowers the current) or have a licensed electrician design the busbars, parallel cables and fusing.',high_c_rate:'This load draws a high current for the battery size: a lead-acid battery then gives well under its rated Ah, so the real backup is shorter than shown, and a lithium battery may shut off. Check the battery\'s maximum discharge current or use a bigger bank.',load_above_cable_table:'This load is above the largest cable in our table. Split it into separate circuits and consult a licensed electrician.',ambient_out_of_range:'Enter an air temperature around the cable between 10 and 60 °C.',circuits_out_of_range:'Enter how many circuits share the conduit or bundle, from 1 to 20.',run_too_long_for_table:'This run is too long for the cables in our table: the voltage drop would exceed the limit. Shorten the run, split the load or consult a licensed electrician.',solar_above_sanctioned:'Your solar array is larger than your sanctioned load. Net billing allows an array up to the sanctioned kW, so the bill and the setups count only the panels that fit. Apply for a higher sanctioned load or plan fewer panels.',price_low_confidence:'The typical price range for this size rests on few published prices, so treat it as a rough guide and compare at least two more quotes.',above_standard_sizes:'This is above the largest standard size we list. Split the array or circuit into two, or ask a licensed electrician or engineer; the sizes shown are the calculated minimums.',generator_above_standard_sizes:'This is above the largest generator size we list. Use two generators on separate circuits or a larger industrial set, and ask a licensed electrician; the size shown is the calculated minimum.',price_data_missing:'Price data could not be loaded. Enter the typical price range yourself or refresh the page.',load_above_generator:'This load is more than the generator can deliver (kVA × power factor). Enter a bigger generator or a smaller load.',fuel_data_missing:'Fuel data could not be loaded. Please refresh the page.',panels_must_be_whole:'Number of panels must be a whole number.',forecast_invalid:'The solar forecast could not be read. The typical day is shown instead.',forecast_unavailable:'The live forecast is not available right now, so a typical day is shown. Try again later.',volts_required_dc:'For DC, enter the battery or system voltage; there is no standard DC voltage to assume.',cable_over_current_rating:'This cable is not rated for this current (in conduit), so it is unsafe even if the voltage drop is small. Use a thicker cable; the wire size calculator checks both.',ampacity_not_checked_aluminium:'The current rating of aluminium cable is not checked here, only its voltage drop. Check the current rating in the cable maker\'s datasheet, or ask a licensed electrician.',hours_year_invalid:'Hours a year must be above 0 and at most 8,760.',duty_invalid:'Compressor on-time must be a share from 0 to 1, e.g. 0.8.',soiling_rate_invalid:'Dust loss per day is a share: 0.003 means 0.3% a day. Maximum 0.05.',backup_above_home:'Backup cannot be more than your list\'s running watts or daily units.',usage_both:'Both boxes are filled, so the units a day are used and the monthly units are left out. Clear the daily box to size from your bill.',per_unit_hidden:'At this small load the cost per unit is not shown: the generator\'s idle fuel would make it look huge. The litres and rupees an hour above still apply.',battery_unknown:'A hybrid price depends on the battery in it. Enter the battery size from the quote in kWh for a fair check; without it the range is for hybrid quotes with any battery, small or large.',typical_used:'Blank boxes in your list use the typical value for that appliance (its listed watts and hours a day, quantity 1). Type your own numbers for an exact result.',internal_non_finite:'These numbers are outside a realistic range. Please check your inputs.',};export{noticeCode,NOTICES};export const errorMessage=(code,c={})=>message(code,{texts:EXACT,...c});
